{"path":"packages/cli/src/pi-import.ts","start":9956,"end":12045,"kind":"delivery-boundary","boundary_name":"readline-close-receipt-and-partial-state","line_end":320,"raw":"	try {
		for (const candidate of candidates) {
			if (candidate.status !== "candidate") {
				results[candidate.kind] = {
					status: candidate.status,
					...(candidate.source ? { source: candidate.source } : {}),
				};
				if (candidate.status === "invalid-source") {
					output.write(
						`${catalogText(catalog, PI_IMPORT_MESSAGE_ID.invalidSource, { filename: candidate.filename })}\n`,
					);
				}
				continue;
			}
			const accepted = parsePiImportAnswer(await ask(questionFor(candidate, catalog)));
			if (!accepted) {
				results[candidate.kind] = { status: "declined", source: candidate.source };
				continue;
			}
			if (!candidate.sourcePath || !candidate.source || !candidate.contents) {
				throw new PiImportError("import candidate is incomplete");
			}
			try {
				writeFilePrivateExclusive(
					pathApi(platform).join(paths.agentDir, candidate.filename),
					candidate.contents,
					paths.agentDir,
				);
				results[candidate.kind] = { status: "imported", source: candidate.source };
				output.write(`${catalogText(catalog, PI_IMPORT_MESSAGE_ID.imported, { filename: candidate.filename })}\n`);
			} catch (error) {
				if (error instanceof Error && "code" in error && error.code === "EEXIST") {
					results[candidate.kind] = { status: "destination-exists", source: candidate.source };
					output.write(`${catalogText(catalog, PI_IMPORT_MESSAGE_ID.skipped, { filename: candidate.filename })}\n`);
					continue;
				}
				throw new PiImportError(
					catalogText(catalog, PI_IMPORT_MESSAGE_ID.importFailed, {
						filename: candidate.filename,
						detail: error instanceof Error ? error.message : String(error),
					}),
				);
			}
		}
	} finally {
		readline?.close();
	}

	if (!results.models || !results.auth) throw new PiImportError("import decisions are incomplete");
	const receipt: PiImportReceipt = {
		schemaVersion: 1,
		models: results.models,
		auth: results.auth,
		decidedAt: (options.now ?? new Date()).toISOString(),
	};
	writeFilePrivateAtomic(statePath, `${JSON.stringify(receipt, null, 2)}\n`, paths.stateDir);
	return receipt;
}
","role":"readline-close-receipt-and-partial-state"}

{"path":"packages/cli/src/pi-import.ts","start":12046,"end":12713,"kind":"delivery-boundary","boundary_name":"outer-optout-lock-finally","line_end":340,"raw":"export async function offerPiConfigurationImport(
	paths: JouzuPaths,
	options: PiImportOptions = {},
): Promise<PiImportReceipt | undefined> {
	const platform = options.platform ?? process.platform;
	const env = options.env ?? process.env;
	if (env.JOUZU_NO_PI_IMPORT === "1") return undefined;
	const release = acquireStateLock({
		path: pathApi(platform).join(paths.stateDir, "pi-import.lock"),
		describe: "Pi import",
		now: options.now,
		onBusy: () => new PiImportError(catalogText(options.catalog ?? defaultCatalog(), PI_IMPORT_MESSAGE_ID.lockBusy)),
	});
	try {
		return await offerPiConfigurationImportLocked(paths, options);
	} finally {
		release();
	}
}
","role":"outer-optout-lock-finally"}

