{"path":"packages/cli/src/cli-messages.ts","start":77706,"end":78570,"kind":"delivery-boundary","boundary_name":"argument-unwrapping-and-native-api-errors","line_end":1226,"raw":"function plainArguments(
	args: Readonly<Record<string, HumanMessageValue>> | undefined,
): Record<string, string | number> | undefined {
	if (args === undefined) return undefined;
	const plain: Record<string, string | number> = {};
	for (const [name, value] of Object.entries(args)) {
		plain[name] = typeof value === "object" ? value.value : value;
	}
	return plain;
}

/**
 * Render one catalog message as plain text without wrapping.
 *
 * The pre-runtime error and help paths write one `console.error`/`console.log`
 * argument, so they need the unwrapped string. A `ProtectedValue` argument is
 * unwrapped to its text, matching the legacy `resolveHumanMessage` behavior.
 */
export function catalogText(
	bundle: CatalogBundle,
	id: string,
	args?: Readonly<Record<string, HumanMessageValue>>,
): string {
	return bundle.format(id, plainArguments(args));
}
","role":"argument-unwrapping-and-native-api-errors"}

{"path":"packages/cli/src/cli-messages.ts","start":78571,"end":79558,"kind":"delivery-boundary","boundary_name":"descriptor-reference-not-runtime-validation","line_end":1253,"raw":"/**
 * The catalog identity of one human message.
 *
 * A message-bearing API takes this type instead of a plain `string`, so a
 * literal sentence does not type-check: the ID is the contract, and the text
 * comes from the resolved catalog. The report is built from `defaultCatalog()`,
 * so a `--json` field keeps its English value while the human renderer is the
 * only reader of the resolved locale.
 */
export interface CatalogMessageRef {
	readonly id: CatalogMessageId;
	readonly args?: Readonly<Record<string, HumanMessageValue>>;
}

/** Build a catalog message reference. */
export function catalogMessage(
	id: CatalogMessageId,
	args?: Readonly<Record<string, HumanMessageValue>>,
): CatalogMessageRef {
	return args === undefined ? { id } : { id, args };
}

/** Render a catalog message reference in the given bundle. */
export function catalogMessageText(bundle: CatalogBundle, message: CatalogMessageRef): string {
	return catalogText(bundle, message.id, message.args);
}
","role":"descriptor-reference-not-runtime-validation"}

{"path":"packages/cli/src/cli-messages.ts","start":79559,"end":80082,"kind":"delivery-boundary","boundary_name":"catalog-error-construction-retention","line_end":1270,"raw":"/**
 * An error whose message is a catalog ID.
 *
 * `Error.message` is the English text, so a generic catch still prints English,
 * while the descriptor lets `handleMainCliError` render the resolved locale
 * through the outer `jouzu.cli.error.generic` wrapper.
 */
export class CatalogError extends Error {
	readonly catalogMessage: CatalogMessageRef;

	constructor(message: CatalogMessageRef) {
		super(catalogMessageText(defaultCatalog(), message));
		this.name = "CatalogError";
		this.catalogMessage = message;
	}
}
","role":"catalog-error-construction-retention"}

{"path":"packages/cli/src/cli-messages.ts","start":80083,"end":80426,"kind":"delivery-boundary","boundary_name":"field-label-fallback-guard","line_end":1276,"raw":"/** Resolve a label by a field's stable id, keeping the report's label when unmapped. */
export function catalogFieldLabel(bundle: CatalogBundle, id: string, fallback: string): string {
	const messageId = DOCTOR_FIELD_LABEL_IDS[id] ?? CATALOG_FIELD_LABEL_IDS[id];
	return messageId === undefined ? fallback : catalogText(bundle, messageId);
}
","role":"field-label-fallback-guard"}

{"path":"packages/cli/src/interactive-startup.ts","start":0,"end":1912,"kind":"delivery-boundary","boundary_name":"interactive-filter-contract","line_end":56,"raw":"const NON_INTERACTIVE_COMMANDS = new Set(["auth", "config", "install", "list", "remove", "uninstall", "update"]);
const NON_INTERACTIVE_FLAGS = new Set([
	"-h",
	"--help",
	"-p",
	"--print",
	"-v",
	"--version",
	"--list-models",
	"--export",
]);
const NON_INTERACTIVE_MODES = new Set(["json", "print", "rpc"]);
const MACHINE_READABLE_MODES = new Set(["json", "rpc"]);

/**
 * True when Pi writes a protocol or event stream to stdout. Callers that decorate process output
 * must pass these modes through byte-exact.
 */
export function usesMachineReadableStdout(args: string[]): boolean {
	for (let index = 0; index < args.length; index += 1) {
		const arg = args[index];
		if (arg === "--mode") {
			if (MACHINE_READABLE_MODES.has(args[index + 1] ?? "")) return true;
			index += 1;
			continue;
		}
		if (arg.startsWith("--mode=") && MACHINE_READABLE_MODES.has(arg.slice("--mode=".length))) return true;
	}
	return false;
}

export interface InteractiveStartupContext {
	stdinIsTTY?: boolean;
	stdoutIsTTY?: boolean;
	env?: NodeJS.ProcessEnv;
}

export function isInteractivePiStartup(args: string[], context: InteractiveStartupContext = {}): boolean {
	const env = context.env ?? process.env;
	const stdinIsTTY = context.stdinIsTTY ?? process.stdin.isTTY === true;
	const stdoutIsTTY = context.stdoutIsTTY ?? process.stdout.isTTY === true;
	if (!stdinIsTTY || !stdoutIsTTY || env.TERM === "dumb") return false;
	if (args.length > 0 && NON_INTERACTIVE_COMMANDS.has(args[0])) return false;

	for (let index = 0; index < args.length; index += 1) {
		const arg = args[index];
		if (NON_INTERACTIVE_FLAGS.has(arg) || arg.startsWith("--export=")) return false;
		if (arg === "--mode") {
			if (NON_INTERACTIVE_MODES.has(args[index + 1] ?? "")) return false;
			index += 1;
			continue;
		}
		if (arg.startsWith("--mode=") && NON_INTERACTIVE_MODES.has(arg.slice("--mode=".length))) return false;
	}
	return true;
}
","role":"interactive-filter-contract"}

{"path":"packages/cli/src/cli.ts","start":5712,"end":7066,"kind":"delivery-boundary","boundary_name":"bootstrap-pi-error-delivery","line_end":188,"raw":"	const main = await import("./main-cli.js");
	await main.runMainCli(args);
