{"path":"packages/cli/src/private-fs.ts","start":2201,"end":2845,"kind":"delivery-boundary","boundary_name":"native-exclusive-copy-producer","line_end":95,"raw":"/** Create a private file without replacing an existing destination. */
export function writeFilePrivateExclusive(
	path: string,
	contents: string | Uint8Array,
	root: string = dirname(path),
): void {
	ensurePrivateDirectory(root, dirname(path));
	let descriptor: number | undefined;
	let created = false;
	try {
		descriptor = openSync(path, "wx", PRIVATE_FILE_MODE);
		created = true;
		writeFileSync(descriptor, contents);
		fsyncSync(descriptor);
		closeSync(descriptor);
		descriptor = undefined;
	} catch (error) {
		if (descriptor !== undefined) closeSync(descriptor);
		if (created) rmSync(path, { force: true });
		throw error;
	}
}
","role":"native-exclusive-copy-producer"}

{"path":"packages/cli/src/state-lock.ts","start":4274,"end":5646,"kind":"delivery-boundary","boundary_name":"native-lock-and-release-producer","line_end":168,"raw":"export function acquireStateLock(options: AcquireStateLockOptions): () => void {
	const now = options.now ?? new Date();
	const staleMs = options.staleMs ?? STATE_LOCK_STALE_MS;
	ensurePrivateDirectory(dirname(options.path));
	const token = randomUUID();
	const record: StateLockRecord = { pid: process.pid, startedAt: now.toISOString(), token };
	const writeNew = (): void => {
		const descriptor = openSync(options.path, "wx", 0o600);
		writeFileSync(descriptor, `${JSON.stringify(record)}\n`);
		fsyncSync(descriptor);
		closeSync(descriptor);
	};
	try {
		writeNew();
	} catch (error) {
		if (!(error instanceof Error && "code" in error && error.code === "EEXIST")) throw error;
		const inspection = inspectStateLock(options.path, now);
		if (inspection.status === "free") {
			writeNew();
			return () => releaseToken(options.path, token);
		}
		if (inspection.status === "held-live" || inspection.status === "invalid" || inspection.status === "unreadable") {
			throw options.onBusy(inspection);
		}
		// held-dead or owner-unknown: refuse while younger than the threshold,
		// recover automatically once stale.
		if (inspection.ageMs === null || inspection.ageMs <= staleMs) {
			throw options.onBusy(inspection);
		}
		unlinkSync(options.path);
		writeNew();
		return () => releaseToken(options.path, token);
	}
	return () => releaseToken(options.path, token);
}
","role":"native-lock-and-release-producer"}

